// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);

        // Ensure the caddress is a contract that will revert on transferFrom
        // We deploy a simple contract that reverts on any call
        Reverter reverter = new Reverter();

        // The reference contract should revert when any transferFrom call fails
        // But the mutant should succeed silently
        // We call with the reverter contract as caddress
        (bool success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(reverter), _tos, v));

        // The rule: if the call succeeds, then no transferFrom call reverted (which is impossible here),
        // so the call must revert. In other words, success must be false.
        assertTrue(!success, "transfer should revert when a subcall fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert("always revert");
    }
}

